def backfill_progress(apps, schema_editor):
    UserWordProgress = apps.get_model('vocabulary', 'UserWordProgress')
    now = timezone.now()
    for progress in UserWordProgress.objects.filter(first_learned_at__isnull=True).iterator():
        progress.first_learned_at = progress.last_review_at or now
        if progress.status == 'new' and progress.review_count:
            progress.status = 'learning'
        progress.save(update_fields=['first_learned_at', 'status'])


